import{_ as l,o as t,c as s,ag as i}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"Java JVM","description":"","frontmatter":{},"headers":[],"relativePath":"interviews/java/jvm.md","filePath":"interviews/java/jvm.md","lastUpdated":1756779477000}'),o={name:"interviews/java/jvm.md"};function e(r,a,n,d,c,p){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="java-jvm" tabindex="-1">Java JVM <a class="header-anchor" href="#java-jvm" aria-label="Permalink to &quot;Java JVM&quot;">​</a></h1><h2 id="类加载器是什么-类加载器有什么作用" tabindex="-1">类加载器是什么?类加载器有什么作用? <a class="header-anchor" href="#类加载器是什么-类加载器有什么作用" aria-label="Permalink to &quot;类加载器是什么?类加载器有什么作用?&quot;">​</a></h2><p>类加载器是动态加载类的字节码.class文件到JVM方法区的对象, 通过类加载器还可以读取classpath下的资源.</p><p>负责加载类的.class文件，加载到JVM方法区中，生成 Class 对象。</p><p>加载器有:</p><ul><li>Bootstrap ClassLoader, 加载 JDK 内部的核心类库</li><li>Platform ClassLoader, 加载JDK下ext包下的扩展类</li><li>System ClassLoader ,加载当前应用 classpath 下的所有 jar 包和类</li></ul><h2 id="类加载器加载类的流程是什么样的" tabindex="-1">类加载器加载类的流程是什么样的? <a class="header-anchor" href="#类加载器加载类的流程是什么样的" aria-label="Permalink to &quot;类加载器加载类的流程是什么样的?&quot;">​</a></h2><ol><li>加载：通过类的全限定名获取字节码文件，并将其转换为方法区内的运行时数据结构。</li><li>验证：对字节码进行校验，确保符合Java虚拟机规范。</li><li>准备：为类的静态变量分配内存，并设置默认初始值。</li><li>解析：将符号引用转换为直接引用，即将类、方法、字段等解析为具体的内存地址。</li><li>初始化：执行类的初始化代码，包括静态变量赋值和静态代码块的执行。</li></ol><ul><li><strong>加载到内存</strong>。<code>.class</code>文件-&gt;字节流-&gt;JVM内存-Class对象</li><li><strong>校验字节码</strong>. 确保 Class 字节流中的信息符合当前虚拟机的要求,不会危害虚拟机自身的安全</li><li><strong>静态变量</strong>分配内存、赋默认值(零值)</li><li><strong>符号</strong>引用转换，<strong>解析</strong>地址. <strong>将常量池的符号引用替换为直接引用的过程</strong></li><li><strong>静态变量</strong>赋值, 静态块执行. <strong>为类的静态变量赋予正确的初始值，JVM 负责对类进行初始化，主要对类变量进行初始化</strong></li></ul><h2 id="类加载器有哪些分类" tabindex="-1">类加载器有哪些分类? <a class="header-anchor" href="#类加载器有哪些分类" aria-label="Permalink to &quot;类加载器有哪些分类?&quot;">​</a></h2><ul><li>bootstrap classloader</li><li>Platform classloader</li><li>System Classloader</li></ul><h2 id="双亲委派模型是什么" tabindex="-1">双亲委派模型是什么? <a class="header-anchor" href="#双亲委派模型是什么" aria-label="Permalink to &quot;双亲委派模型是什么?&quot;">​</a></h2><p>概念: 双亲委派模型(机制)是一种类加载机制, 在类加载时按照一定的层次关系逐级委托给父类加载器进行加载.</p><p>过程: 当一个类加载器接收到类加载请求时，会先判断是否加载过, 如果没有加载过, 会把请求委派给父类加载器去完成，依次递归，直到最顶层的类加载器，如果父类加载器无法完成加载请求，子类加载器才会尝试自己去加载。</p><p>好处/原因: ①避免类的重复加载, ②保证核心类库的安全性(防止被篡改)</p><p><strong>核心: 已经加载了的类, 直接返回; 没有加载的类, 委派给父类加载器去加载</strong></p><ol><li>在类加载的时候，系统会首先判断当前类是否被加载过。已经被加载的类会直接返回，否则会把这个请求委派给父类加载器去完成（每个父类加载器都会走一遍这个流程）。</li><li>只有当父加载器反馈自己无法完成这个加载请求（它的搜索范围中没有找到所需的类）时，子加载器才会尝试自己去加载（调用自己的 findClass() 方法来加载类）</li><li>如果子类加载器也无法加载这个类，那么它会抛出一个 ClassNotFoundException 异常。</li></ol>',17)])])}const g=l(o,[["render",e]]);export{m as __pageData,g as default};
